// ==== src/core/modelRegistry.js ====


class ModelRegistry {
  static MODELS = [
    // === Gemini ===
    { pattern: /gemini.*2\.5.*pro/i, name: 'Gemini 2.5 Pro', limit: 1000000, platform: 'gemini', multiplier: 1.05 },
    { pattern: /gemini.*2\.5.*flash/i, name: 'Gemini 2.5 Flash', limit: 1000000, platform: 'gemini', multiplier: 1.05 },
    { pattern: /gemini.*2\.0.*flash/i, name: 'Gemini 2.0 Flash', limit: 1000000, platform: 'gemini', multiplier: 1.05 },
    { pattern: /gemini.*1\.5.*pro/i, name: 'Gemini 1.5 Pro', limit: 2000000, platform: 'gemini', multiplier: 1.05 },
    { pattern: /gemini.*1\.5/i, name: 'Gemini 1.5 Flash', limit: 1000000, platform: 'gemini', multiplier: 1.05 },
    { pattern: /gemini/i, name: 'Gemini (default)', limit: 1000000, platform: 'gemini', multiplier: 1.05 },

    // === OpenAI / ChatGPT ===
    { pattern: /gpt-?4\.?1/i, name: 'GPT-4.1', limit: 1000000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /gpt-?4o-?mini/i, name: 'GPT-4o mini', limit: 128000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /gpt-?4o/i, name: 'GPT-4o', limit: 128000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /o4-?mini/i, name: 'o4-mini', limit: 200000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /o3-?mini/i, name: 'o3-mini', limit: 200000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /o3/i, name: 'o3', limit: 200000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /o1-?mini/i, name: 'o1-mini', limit: 128000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /o1/i, name: 'o1', limit: 200000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /gpt-?4/i, name: 'GPT-4', limit: 128000, platform: 'chatgpt', multiplier: 1.00 },
    { pattern: /chatgpt/i, name: 'ChatGPT (GPT-4o)', limit: 128000, platform: 'chatgpt', multiplier: 1.00 },

    // === Claude (Anthropic) ===
    { pattern: /claude.*opus.*4/i, name: 'Claude Opus 4', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude.*sonnet.*4/i, name: 'Claude Sonnet 4', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude.*4/i, name: 'Claude 4', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude.*3[.\- ]7/i, name: 'Claude 3.7 Sonnet', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude.*3[.\- ]5.*sonnet/i, name: 'Claude 3.5 Sonnet', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude.*3/i, name: 'Claude 3', limit: 200000, platform: 'claude', multiplier: 1.15 },
    { pattern: /claude/i, name: 'Claude (default)', limit: 200000, platform: 'claude', multiplier: 1.15 },

    // === DeepSeek ===
    { pattern: /deepseek.*r1/i, name: 'DeepSeek-R1', limit: 128000, platform: 'deepseek', multiplier: 1.10 },
    { pattern: /deepseek.*v3/i, name: 'DeepSeek-V3', limit: 128000, platform: 'deepseek', multiplier: 1.10 },
    { pattern: /deepseek/i, name: 'DeepSeek (default)', limit: 128000, platform: 'deepseek', multiplier: 1.10 },

    // === Kimi ===
    { pattern: /k1\.5|kimi.*k1/i, name: 'Kimi K1.5', limit: 2000000, platform: 'kimi', multiplier: 1.10 },
    { pattern: /kimi/i, name: 'Kimi Moonshot', limit: 128000, platform: 'kimi', multiplier: 1.10 },

    // === Qwen ===
    { pattern: /qwen.*3/i, name: 'Qwen 3', limit: 128000, platform: 'qwen', multiplier: 1.10 },
    { pattern: /qwen.*2\.5/i, name: 'Qwen 2.5', limit: 128000, platform: 'qwen', multiplier: 1.10 },
    { pattern: /qwen/i, name: 'Qwen (default)', limit: 128000, platform: 'qwen', multiplier: 1.10 }
  ];

  /**
   * Resolves model info based on platform key and DOM-extracted text.
   * @param {string} platformKey
   * @param {string} scrapedModelText
   * @returns {{ name: string, limit: number, platform: string, multiplier: number }}
   */
  static getModelInfo(platformKey, scrapedModelText = '') {
    if (scrapedModelText) {
      const match = this.MODELS.find((m) => m.pattern.test(scrapedModelText));
      if (match) return match;
    }

    // Default fallback by platform key
    const fallback = this.MODELS.find((m) => m.platform === platformKey);
    if (fallback) return fallback;

    return { name: 'Generic Model', limit: 128000, platform: 'generic', multiplier: 1.0 };
  }

  /**
   * Resolves model info from an API model ID captured by the network
   * interceptor (e.g. "gpt-4.1", "claude-sonnet-4-5", "gemini-2.5-pro").
   * API IDs often embed model family but not the exact advertised name;
   * this returns the best-matching registry entry, or null when the ID
   * cannot be attributed to any registered model.
   * @param {string} modelId
   * @returns {Object|null}
   */
  static getModelByApiId(modelId) {
    if (!modelId || typeof modelId !== 'string') return null;

    // Try progressively less-normalized forms so both "gpt-4.1" and
    // "claude-3-7-sonnet" match their registry patterns:
    //   1. raw (with separators)   "claude-3-7-sonnet"
    //   2. compacted              "gpt-4.1" -> "gpt4.1"
    //   3. hyphen -> dot          "claude-3-7-sonnet" -> "claude.3.7.sonnet"
    const candidates = [
      modelId.trim(),
      modelId.replace(/[-_]/g, ''),
      modelId.replace(/-/g, '.')
    ];

    for (const candidate of candidates) {
      const match = this.MODELS.find((m) => m.pattern.test(candidate));
      if (match) return match;
    }
    return null;
  }

  /**
   * Formats token counts nicely (e.g. 1000000 -> 1M, 128000 -> 128k, 64000 -> 64k)
   * @param {number} tokens
   * @returns {string}
   */
  static formatTokenCount(tokens) {
    if (!tokens || isNaN(tokens)) return '0';
    if (tokens >= 1000000) {
      const num = tokens / 1000000;
      return `${num % 1 === 0 ? num : num.toFixed(1)}M`;
    }
    if (tokens >= 1000) {
      const num = tokens / 1000;
      return `${num % 1 === 0 ? num : num.toFixed(1)}k`;
    }
    return tokens.toLocaleString();
  }
}


// ==== src/content/adapters/baseAdapter.js ====


class BaseAdapter {
  constructor(config = {}) {
    this.platformKey = config.platformKey || 'generic';
    this.hardLimitTokens = config.hardLimitTokens || 128000;
    this.tokenMultiplier = config.tokenMultiplier || 1.0;
    this._interceptedModelId = null;
  }

  /**
   * Records a model ID captured by the network interceptor (main world).
   * @param {string} modelId
   */
  setInterceptedModel(modelId) {
    if (modelId && typeof modelId === 'string') {
      this._interceptedModelId = modelId;
    }
  }

  /**
   * Tests whether this adapter handles the given URL hostname.
   * @param {string} hostname
   * @returns {boolean}
   */
  matches(hostname) {
    return false;
  }

  /**
   * Locates the main chat message container element.
   * @returns {HTMLElement}
   */
  getChatContainer() {
    return document.querySelector('main') || document.body;
  }

  /**
   * Extracts model name text from the DOM if present.
   * @returns {string}
   */
  extractModelName() {
    return '';
  }

  /**
   * Two-phase model resolution (SPEC-1 §3.4):
   * Phase 1 — check the network-intercepted API model ID.
   * Phase 2 — fall back to DOM scraping + registry match.
   * @returns {{ name: string, limit: number, platform: string, multiplier: number, source: string }}
   */
  getDetectedModel() {
    if (this._interceptedModelId) {
      const match = ModelRegistry.getModelByApiId(this._interceptedModelId);
      if (match) {
        return { ...match, source: 'network' };
      }
    }
    const scrapedText = this.extractModelName();
    return { ...ModelRegistry.getModelInfo(this.platformKey, scrapedText), source: 'dom' };
  }

  /**
   * Resolves model info and context limit.
   * @returns {{ name: string, limit: number, platform: string, multiplier: number }}
   */
  getModelInfo() {
    return this.getDetectedModel();
  }

  /**
   * Scrapes chat messages from the DOM.
   * @returns {Array<{ id: string, role: 'user'|'assistant', text: string, codeText: string, timestamp: number }>}
   */
  extractMessages() {
    return [];
  }

  /**
   * Cleans an element's text by stripping UI buttons, SVGs, and hidden elements.
   * @param {HTMLElement} element
   * @returns {string}
   */
  cleanElementText(element) {
    if (!element) return '';
    const clone = element.cloneNode(true);

    const selectorsToRemove = [
      'button',
      'svg',
      '.copy-button',
      '.action-buttons',
      '.sr-only',
      'style',
      'script',
      '[aria-hidden="true"]'
    ];

    selectorsToRemove.forEach((selector) => {
      clone.querySelectorAll(selector).forEach((node) => node.remove());
    });

    return clone.textContent ? clone.textContent.trim() : '';
  }

  /**
   * Extracts text from pre/code blocks inside a message element.
   * @param {HTMLElement} element
   * @returns {string}
   */
  extractCodeText(element) {
    if (!element) return '';
    let codeContent = '';
    element.querySelectorAll('pre, code').forEach((block) => {
      codeContent += ' ' + block.textContent;
    });
    return codeContent.trim();
  }

  /**
   * Locates the primary text input element in the chat interface.
   * @returns {HTMLElement|null}
   */
  getChatInput() {
    return document.querySelector('textarea, div[contenteditable="true"]');
  }
}


// ==== src/content/adapters/chatgptAdapter.js ====


class ChatGPTAdapter extends BaseAdapter {
  constructor() {
    super({
      platformKey: 'chatgpt',
      hardLimitTokens: 128000,
      tokenMultiplier: 1.00
    });
  }

  matches(hostname) {
    return /chatgpt\.com|chat\.openai\.com/.test(hostname);
  }

  extractModelName() {
    // 1. Stable data-testid / aria attributes first
    const selectors = [
      '[data-testid="model-switcher-dropdown-button"]',
      '[data-testid="model-switcher-button"]',
      'button[data-testid*="model"]',
      '[data-testid*="model-picker"]',
      'button[id^="radix-"]',
      '[aria-haspopup="menu"]',
      'div[class*="model-name"]'
    ];

    for (const sel of selectors) {
      const el = document.querySelector(sel);
      if (el && el.textContent) {
        const text = el.textContent.trim();
        if (/gpt|o1|o3|o4/i.test(text)) return text;
      }
    }

    // 2. Text-content matching near known UI regions
    const regions = document.querySelectorAll('header, nav, [class*="model"], [data-testid*="model"]');
    for (const region of regions) {
      const text = region.textContent ? region.textContent.trim() : '';
      const m = text.match(/(gpt-?4[^\s"]*|o[134]-?mini|o[134]|chatgpt[^\s"]*)/i);
      if (m) return m[0];
    }

    return 'ChatGPT (GPT-4o)';
  }

  extractMessages() {
    const messages = [];
    const elements = document.querySelectorAll('[data-message-author-role], article');

    elements.forEach((el, index) => {
      let role = el.getAttribute('data-message-author-role');
      if (!role) {
        if (el.querySelector('[data-message-author-role="user"]')) {
          role = 'user';
        } else {
          role = 'assistant';
        }
      }

      const text = this.cleanElementText(el);
      const codeText = this.extractCodeText(el);

      if (text) {
        messages.push({
          id: el.id || `cg-msg-${index}`,
          role: role === 'user' ? 'user' : 'assistant',
          text,
          codeText,
          timestamp: Date.now()
        });
      }
    });

    return messages;
  }

  getChatInput() {
    return document.querySelector('#prompt-textarea') || document.querySelector('textarea');
  }
}


// ==== src/content/adapters/claudeAdapter.js ====


class ClaudeAdapter extends BaseAdapter {
  constructor() {
    super({
      platformKey: 'claude',
      hardLimitTokens: 200000,
      tokenMultiplier: 1.15
    });
  }

  matches(hostname) {
    return /claude\.ai/.test(hostname);
  }

  extractModelName() {
    // 1. Stable data-testid / aria attributes first
    const selectors = [
      'button[data-testid="model-selector"]',
      '[data-testid*="model"]',
      'div[class*="ModelSelector"]',
      'div[class*="model-selector"]',
      'button[aria-haspopup="menu"]'
    ];

    for (const sel of selectors) {
      const el = document.querySelector(sel);
      if (el && el.textContent) {
        const text = el.textContent.trim();
        if (/claude|opus|sonnet|haiku/i.test(text)) return text;
      }
    }

    // 2. Text-content matching in header / top nav
    const regions = document.querySelectorAll('header, nav, [class*="model"], [data-testid*="model"]');
    for (const region of regions) {
      const text = region.textContent ? region.textContent.trim() : '';
      const m = text.match(/(claude[^\s"]*|opus[^\s"]*|sonnet[^\s"]*|haiku[^\s"]*)/i);
      if (m) return m[0];
    }

    return 'Claude (default)';
  }

  extractMessages() {
    const messages = [];

    const selectors = [
      '.font-claude-message',
      '.user-message-block',
      '[data-is-streaming]',
      'div[class*="ChatMessage"]',
      '[data-testid*="user-message"]',
      '[data-testid*="assistant-message"]'
    ];

    const elements = document.querySelectorAll(selectors.join(', '));

    elements.forEach((el, index) => {
      let role = 'assistant';
      if (el.classList.contains('user-message-block') || el.querySelector('.user-message-block') ||
          (el.getAttribute('data-testid') || '').includes('user-message')) {
        role = 'user';
      }

      const text = this.cleanElementText(el);
      const codeText = this.extractCodeText(el);

      if (text) {
        messages.push({
          id: el.id || `claude-msg-${index}`,
          role,
          text,
          codeText,
          timestamp: Date.now()
        });
      }
    });

    return messages;
  }

  getChatInput() {
    return document.querySelector('fieldset div[contenteditable="true"]') ||
           document.querySelector('div[contenteditable="true"]');
  }
}


// ==== src/content/adapters/geminiAdapter.js ====


class GeminiAdapter extends BaseAdapter {
  constructor() {
    super({
      platformKey: 'gemini',
      hardLimitTokens: 1000000,
      tokenMultiplier: 1.05
    });
  }

  matches(hostname) {
    return /gemini\.google\.com/.test(hostname);
  }

  extractModelName() {
    // 1. Stable data-test-id / aria attributes first
    const selectors = [
      '[data-test-id="model-picker-button"]',
      '[data-testid="model-picker-button"]',
      '.model-picker-button',
      'mat-select',
      '.model-title',
      '[aria-label*="Gemini"]',
      'button[aria-haspopup="menu"]'
    ];

    for (const sel of selectors) {
      const elements = document.querySelectorAll(sel);
      for (const el of elements) {
        const text = el.textContent ? el.textContent.trim() : '';
        if (/flash|pro|gemini|thinking|2\.5|2\.0|1\.5/i.test(text)) {
          return text;
        }
      }
    }

    // 2. Text-content matching in header
    const regions = document.querySelectorAll('header, nav, [class*="model"], [data-test*="model"]');
    for (const region of regions) {
      const text = region.textContent ? region.textContent.trim() : '';
      const m = text.match(/(gemini[^\s"]*|2\.5[^\s"]*pro|2\.5[^\s"]*flash|2\.0[^\s"]*flash|1\.5[^\s"]*)/i);
      if (m) return m[0];
    }

    return 'Gemini (default)';
  }

  extractMessages() {
    const messages = [];

    const querySelectors = [
      'message-content',
      '.user-query',
      '.query-content',
      '.model-response-text',
      '.response-container',
      '[data-testid*="user-query"]',
      '[data-testid*="assistant-response"]'
    ];

    const elements = document.querySelectorAll(querySelectors.join(', '));

    elements.forEach((el, index) => {
      let role = 'assistant';
      if (el.classList.contains('user-query') || el.classList.contains('query-content') ||
          el.closest('.user-query-container') || (el.getAttribute('data-testid') || '').includes('user-query')) {
        role = 'user';
      }

      const text = this.cleanElementText(el);
      const codeText = this.extractCodeText(el);

      if (text) {
        messages.push({
          id: el.id || `gemini-msg-${index}`,
          role,
          text,
          codeText,
          timestamp: Date.now()
        });
      }
    });

    return messages;
  }

  getChatInput() {
    return document.querySelector('.input-area textarea') ||
           document.querySelector('textarea[aria-label]') ||
           document.querySelector('div[contenteditable="true"]');
  }
}


// ==== src/content/adapters/deepseekAdapter.js ====


class DeepSeekAdapter extends BaseAdapter {
  constructor() {
    super({
      platformKey: 'deepseek',
      hardLimitTokens: 128000, // DeepSeek V3 / R1 default limit
      tokenMultiplier: 1.10
    });
  }

  matches(hostname) {
    return /deepseek\.com/.test(hostname);
  }

  extractModelName() {
    const selectors = ['div[class*="model"]', '.model-select', 'header span'];
    for (const sel of selectors) {
      const el = document.querySelector(sel);
      if (el && el.textContent) {
        const text = el.textContent.trim();
        if (/deepseek|r1|v3/i.test(text)) return text;
      }
    }
    return 'DeepSeek (default)';
  }

  extractMessages() {
    const messages = [];
    const selectors = ['._user-message', '.ds-markdown', 'div[class*="chat-message"]'];
    const elements = document.querySelectorAll(selectors.join(', '));

    elements.forEach((el, index) => {
      let role = 'assistant';
      if (el.classList.contains('_user-message') || el.closest('._user-message')) {
        role = 'user';
      }

      const text = this.cleanElementText(el);
      const codeText = this.extractCodeText(el);

      if (text) {
        messages.push({
          id: el.id || `ds-msg-${index}`,
          role,
          text,
          codeText,
          timestamp: Date.now()
        });
      }
    });

    return messages;
  }

  getChatInput() {
    return document.querySelector('#chat-input') || document.querySelector('textarea');
  }
}


